import zipfile
import re
import xml.etree.ElementTree as ET

NS = {'m': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main',
      'r': 'http://schemas.openxmlformats.org/officeDocument/2006/relationships'}

with zipfile.ZipFile('budget.xlsx') as z:
    names = z.namelist()
    print("Files in archive:")
    for n in names:
        print(" ", n)

    # shared strings
    shared = []
    if 'xl/sharedStrings.xml' in names:
        root = ET.fromstring(z.read('xl/sharedStrings.xml'))
        for si in root.findall('m:si', NS):
            text = ''.join(t.text or '' for t in si.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t'))
            shared.append(text)

    # workbook sheet list
    wb_root = ET.fromstring(z.read('xl/workbook.xml'))
    sheets = []
    for sh in wb_root.find('m:sheets', NS):
        sheets.append((sh.get('name'), sh.get('{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id')))
    print("\nSheets:", sheets)

    # workbook rels to map r:id -> sheet file
    rels_root = ET.fromstring(z.read('xl/_rels/workbook.xml.rels'))
    rels = {}
    for rel in rels_root:
        rels[rel.get('Id')] = rel.get('Target')

    def col_to_idx(ref):
        m = re.match(r'([A-Z]+)(\d+)', ref)
        col = 0
        for ch in m.group(1):
            col = col * 26 + (ord(ch) - ord('A') + 1)
        return col - 1

    for name, rid in sheets:
        target = rels[rid]
        if not target.startswith('xl/'):
            target = 'xl/' + target
        print(f"\n=== Sheet: {name} ===")
        root = ET.fromstring(z.read(target))
        sd = root.find('m:sheetData', NS)
        for row in sd.findall('m:row', NS):
            for c in row.findall('m:c', NS):
                ref = c.get('r')
                t = c.get('t')
                v = c.find('m:v', NS)
                val = None
                if v is not None:
                    if t == 's':
                        val = shared[int(v.text)]
                    elif t == 'str':
                        val = v.text
                    else:
                        val = v.text
                if val is not None:
                    print(f"  {ref}: {val!r}")

